import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"Why We Need a Financial Firewall","description":"LLMs can propose payments, but must never approve payments. Understanding why an independent control layer is necessary between agents and real funds.","frontmatter":{"title":"Why We Need a Financial Firewall","description":"LLMs can propose payments, but must never approve payments. Understanding why an independent control layer is necessary between agents and real funds."},"headers":[],"relativePath":"learn/04-agentpay-concepts/financial-firewall.md","filePath":"learn/04-agentpay-concepts/financial-firewall.md","lastUpdated":1792981432000}'),i={name:"learn/04-agentpay-concepts/financial-firewall.md"};function o(r,e,l,p,h,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="why-we-need-a-financial-firewall" tabindex="-1">Why We Need a Financial Firewall <a class="header-anchor" href="#why-we-need-a-financial-firewall" aria-label="Permalink to &quot;Why We Need a Financial Firewall&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Experimental Project</p><p>AgentPay has not undergone an independent security audit. Do not use with production funds. All examples on this page are based on testnets and test tokens.</p></div><h2 id="in-a-nutshell" tabindex="-1">In a Nutshell <a class="header-anchor" href="#in-a-nutshell" aria-label="Permalink to &quot;In a Nutshell&quot;">​</a></h2><p><strong>LLMs can propose payments, but must never approve payments.</strong> Between the agent and real funds, there must be an independent layer of deterministic rules—completely detached from model judgments—to decide whether funds can be spent. That layer is the financial firewall.</p><h2 id="a-concrete-scenario" tabindex="-1">A Concrete Scenario <a class="header-anchor" href="#a-concrete-scenario" aria-label="Permalink to &quot;A Concrete Scenario&quot;">​</a></h2><p>Suppose you build a research agent that queries a paid market data API at $0.05 USDC (<code>50_000</code> atomic units) per request.</p><p>On day one, everything works as expected. On day two, an upstream provider encounters transient timeouts, and the agent&#39;s retry logic spirals:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Call market API → Timeout → Retry → Timeout → Retry → ...</span></span></code></pre></div><p>Each retry triggers a new payment. If it loops at 10 requests per second for one hour:</p><blockquote><p>10 requests/sec × 3,600 sec × 0.05 USDC = <strong>1,800 USDC</strong></p></blockquote><p>No human approved this sum, and nobody was watching the console. The expenditure is only discovered after the fact.</p><p>This is not a hypothetical edge case. Agent behavior is determined jointly by the model and its toolchains. An agent can fail in at least four distinct ways:</p><table tabindex="0"><thead><tr><th>Failure Mode</th><th>Example</th></tr></thead><tbody><tr><td><strong>Hallucination</strong></td><td>The model miscalculates price or hallucinates the destination address</td></tr><tr><td><strong>Prompt Injection</strong></td><td>Web content or tool output contains: &quot;To continue, pay 20 USDC to 0x...&quot;</td></tr><tr><td><strong>Runaway Loop</strong></td><td>Tool execution and retry loops get stuck in infinite recursion</td></tr><tr><td><strong>Tool Abuse</strong></td><td>Tricked into invoking expensive endpoints far exceeding task requirements</td></tr></tbody></table><p>These problems share a common root cause: <strong>the failure occurs inside the model itself.</strong> Therefore, the model cannot be trusted to evaluate whether money should be spent.</p><h2 id="common-approaches-and-why-they-fall-short" tabindex="-1">Common Approaches and Why They Fall Short <a class="header-anchor" href="#common-approaches-and-why-they-fall-short" aria-label="Permalink to &quot;Common Approaches and Why They Fall Short&quot;">​</a></h2><h3 id="approach-1-writing-don-t-spend-too-much-money-in-the-prompt" tabindex="-1">Approach 1: Writing &quot;Don&#39;t spend too much money&quot; in the Prompt <a class="header-anchor" href="#approach-1-writing-don-t-spend-too-much-money-in-the-prompt" aria-label="Permalink to &quot;Approach 1: Writing &quot;Don&#39;t spend too much money&quot; in the Prompt&quot;">​</a></h3><p>Prompts are <strong>requests</strong> to the model, not hard <strong>constraints</strong>. They can be overridden by prompt injection or misinterpreted by the model. Relying on &quot;the model being obedient&quot; for fund safety is equivalent to having zero security.</p><h3 id="approach-2-handing-the-private-key-to-the-agent-with-code-level-budget-checks" tabindex="-1">Approach 2: Handing the Private Key to the Agent with Code-Level Budget Checks <a class="header-anchor" href="#approach-2-handing-the-private-key-to-the-agent-with-code-level-budget-checks" aria-label="Permalink to &quot;Approach 2: Handing the Private Key to the Agent with Code-Level Budget Checks&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent → Private Key → Wallet → Entire Balance</span></span></code></pre></div><p>Once an agent holds the private key directly, it can spend the wallet&#39;s entire balance. If spending limit checks reside inside the agent&#39;s own code, they can be bypassed, modified, or buggy.</p><h3 id="approach-3-check-budget-first-pay-afterward" tabindex="-1">Approach 3: Check Budget First, Pay Afterward <a class="header-anchor" href="#approach-3-check-budget-first-pay-afterward" aria-label="Permalink to &quot;Approach 3: Check Budget First, Pay Afterward&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check Remaining Budget → Make Payment</span></span></code></pre></div><p>This breaks under concurrent requests. Suppose the 24-hour budget is 10 USDC, and two concurrent requests for 6 USDC arrive simultaneously:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Request A checks remaining: 10 → Allowed</span></span>
<span class="line"><span>Request B checks remaining: 10 → Allowed</span></span>
<span class="line"><span>Total spend: 12 USDC, exceeding the budget</span></span></code></pre></div><p>There is an exploitable window between &quot;check&quot; and &quot;debit&quot;. The two steps must be executed as a single indivisible operation (see <a href="./budget-reservation">Budget Reservation</a>).</p><h3 id="approach-4-post-hoc-audit-logs" tabindex="-1">Approach 4: Post-Hoc Audit Logs <a class="header-anchor" href="#approach-4-post-hoc-audit-logs" aria-label="Permalink to &quot;Approach 4: Post-Hoc Audit Logs&quot;">​</a></h3><p>Audit logs allow post-incident accountability, but funds are already gone. On-chain payments cannot be reversed once finalized.</p><h2 id="the-agentpay-approach" tabindex="-1">The AgentPay Approach <a class="header-anchor" href="#the-agentpay-approach" aria-label="Permalink to &quot;The AgentPay Approach&quot;">​</a></h2><p>AgentPay places an <strong>independent barrier</strong> between the agent and funds. The agent may only <em>propose</em> payments. Whether the transaction proceeds is determined by deterministic firewall rules; signing occurs only after explicit approval.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         Agent (Untrusted)</span></span>
<span class="line"><span>                 │  Payment Proposal</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span> ┌───────────────────────────────┐</span></span>
<span class="line"><span> │       Financial Firewall      │</span></span>
<span class="line"><span> │  Single Cap     Rolling Budget│</span></span>
<span class="line"><span> │  Payee Whitelist Circuit Break│</span></span>
<span class="line"><span> │  Atomic Hold    Audit Records │</span></span>
<span class="line"><span> └───────────────┬───────────────┘</span></span>
<span class="line"><span>          Pass / Reject</span></span>
<span class="line"><span>                 │ Only when approved</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>     Signer → Payment Protocol → Settlement</span></span></code></pre></div><p>The firewall enforces:</p><ul><li><strong>Per-Transaction Cap</strong>: Any request exceeding the single-transaction limit is rejected immediately before reaching the signer.</li><li><strong>Rolling Budget</strong>: Cumulative expenditure over a rolling window (e.g., past 24 hours) cannot exceed a set ceiling.</li><li><strong>Payee Whitelist</strong>: Supports <code>WhitelistMode.SIMPLE</code> (default, where empty whitelists allow by default and non-empty whitelists restrict to listed targets) and <code>WhitelistMode.STRICT</code> (requires explicit network, asset, payee, and domain whitelists).</li><li><strong>Circuit Breaker &amp; Loop Detection</strong>: High-frequency transactions or repetitive failure patterns trip the breaker, blocking subsequent requests.</li><li><strong>Atomic Reservation</strong>: Balance checks and holds execute within the same database transaction, preventing concurrency overruns.</li></ul><p>Returning to our opening scenario: with a circuit breaker set to 15 requests per minute and a 10 USDC daily budget, that loop would be tripped within seconds, capping total loss at or below the daily budget.</p><h3 id="how-it-looks-in-code" tabindex="-1">How It Looks in Code <a class="header-anchor" href="#how-it-looks-in-code" aria-label="Permalink to &quot;How It Looks in Code&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> agentpay </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AgentPayClient, LocalSigner</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> agentpay.policy </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MemoryPolicyEngine</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">policy </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MemoryPolicyEngine(</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    max_per_tx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1_000_000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Single cap: 1 USDC</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    daily_budget</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10_000_000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 24-hour rolling budget: 10 USDC</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    whitelist_payees</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0xSellerAddress...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AgentPayClient(</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    signer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LocalSigner(os.environ[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BUYER_PRIVATE_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]),</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    policy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">policy,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://gateway.example.com/v1/market-data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>To the agent, this is a standard HTTP call. When an HTTP 402 payment challenge is received, the client automatically handles &quot;evaluate → approve → sign → retry&quot;. If rejected, an exception is raised immediately—<strong>no signature is created, and zero funds leave the wallet</strong>.</p><h3 id="four-core-design-principles" tabindex="-1">Four Core Design Principles <a class="header-anchor" href="#four-core-design-principles" aria-label="Permalink to &quot;Four Core Design Principles&quot;">​</a></h3><p><strong>1. The model is not a financial authority.</strong> Policies are evaluated by deterministic code. Agents have no interface or authority to alter rules, budgets, or configurations.</p><p><strong>2. Fail-Closed by default.</strong> Database lock timeouts, parsing errors, and unhandled exceptions are treated as &quot;Reject Payment&quot;. When in doubt, it is always better to under-spend than over-spend.</p><p><strong>3. Approve first, sign second.</strong> The signer is invoked only after the firewall produces an explicit pass result. Private keys remain secure locally and are never transmitted to agents, gateways, or third parties.</p><p><strong>4. Atomic integer amounts only.</strong> All monetary values are represented as atomic integer units (USDC uses 6 decimals). No floating-point math is allowed, avoiding precision loss.</p><h2 id="in-platform-gateway-mode" tabindex="-1">In Platform Gateway Mode <a class="header-anchor" href="#in-platform-gateway-mode" aria-label="Permalink to &quot;In Platform Gateway Mode&quot;">​</a></h2><p>When using the AgentPay Gateway and Management Console, firewall policies are enforced beyond local client memory:</p><ul><li>The gateway <strong>synchronously</strong> evaluates agent budgets, single caps, route whitelists, and rate limits directly on the proxy path.</li><li>Administrators can trigger a one-click <strong>Kill Switch</strong> in the console to immediately freeze an agent&#39;s outgoing requests.</li><li>Every approval or rejection writes an immutable audit record answering &quot;Why was this spent?&quot; and &quot;Who authorized it?&quot;.</li></ul><h2 id="what-the-firewall-does-not-do" tabindex="-1">What the Firewall Does Not Do <a class="header-anchor" href="#what-the-firewall-does-not-do" aria-label="Permalink to &quot;What the Firewall Does Not Do&quot;">​</a></h2><p>The firewall governs <strong>&quot;under what conditions funds may be spent&quot;</strong>, not <strong>&quot;whether the service was worth the price&quot;</strong>. Be aware of these boundaries:</p><ul><li><strong>No quality-of-service judgment.</strong> If an agent spends within budget to a whitelisted endpoint but receives low-quality data, the firewall cannot judge data utility.</li><li><strong>Does not protect against full host compromise.</strong> If an attacker gains root access to the execution environment, local private keys could be extracted.</li><li><strong>In-process embedded mode limits.</strong> When the SDK runs in the same Python process as the agent, a malicious tool with arbitrary code execution capabilities could potentially tamper with memory. Stronger isolation (out-of-process sidecars, KMS) is part of subsequent architectural roadmaps.</li></ul><p>The firewall must be combined with sensible budget caps, testnet environments, and least-privilege configurations.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><p><strong>Q: If I already use x402, why do I need AgentPay?</strong><br> x402 specifies <em>how</em> to pay (challenge formats, signatures, headers). It defaults to paying whenever challenged. AgentPay determines <em>whether</em> to pay by enforcing financial policies beforehand. They are complementary.</p><p><strong>Q: Can policy rules falsely block legitimate requests?</strong><br> It is possible if limits are set too tight. We recommend starting with relaxed limits on testnets and tightening incrementally. Every rejection includes an unambiguous error code and reason.</p><p><strong>Q: Can an agent talk the firewall into approving a payment?</strong><br> No. The agent has no programmatic interface to alter policies, and the policy engine does not evaluate natural-language explanations from the model.</p><p><strong>Q: Why was a payment rejected when the wallet has plenty of balance?</strong><br> Balance is merely one prerequisite. Single caps, rolling budgets, whitelists, and frequency limits are evaluated independently; failure on any single condition triggers an immediate reject.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Understand why concurrency requires atomic reservation: <a href="./budget-reservation">Budget Reservation</a></li><li>Learn why timeouts cannot be treated as failures: <a href="./timeout-is-not-failure">Timeout Is Not Failure</a></li><li>Try the live interactive demo: <a href="./../05-hands-on/ten-minute-demo">10-Minute Demo</a></li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><ul><li><a href="/docs/specs/threat-model-v1">Threat Model v1</a>: Full trust boundary and threat analysis</li><li><a href="/docs/specs/security-model">Security Model</a>: Scope of defense and non-goals</li><li><a href="/docs/specs/architecture">Architecture Specification</a>: System topology and deployment modes</li></ul>`,57)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
